 "id": "fa-protection",
 "subject": "firstaid",
 "group": "Emergency care",
 "title": "Protection and alert",
 "sourceFile": "First AID 1.pdf (First Aid and Vital Functions, Pr Amal Haoudar)",
 "sourceUrl": "https://drive.google.com/file/d/1Iw05IC9gLcocJGGLEGcBLsYykNRIhNjn/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> Slides that only show pictures are covered in outline. If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>First aid is the immediate care given to an injured or suddenly ill person before professional help arrives. Its three aims: <strong>preserve life, prevent worsening, promote recovery</strong>. It applies to medical emergencies (chest pain, tachycardia, acute dyspnoea, altered mental status), trauma, environmental conditions, respiratory problems, intoxications and envenomations.</p>"
  },
  {
   "id": "s1",
   "title": "The first responder and the scene",
   "html": "<p>A first responder can be a professional, a trained person or a layperson. The role: stay calm, act within your training, call for professional help, and <strong>secure the scene before acting</strong>. Priorities: emotional self-control, then the safety of yourself, your team and the victim. Do not rush in; eliminate physical dangers; do not assume you know how injured the victim is; protect yourself from blood and body fluids with <strong>PPE</strong>.</p><p><strong>Hazards</strong>: biohazards and chemicals, fire and fumes, electricity, water, traffic, falling objects and unstable structures, slippery surfaces, sharp edges and glass, explosives, confined spaces, heights, and aggressive people.</p><p><strong>Road accident</strong>: switch off all ignitions, move casualties to safety, immobilise an upright vehicle (hand brake, blocks under the wheels), never try to right a vehicle on its side, stabilise it only if safe and trained.</p>"
  },
  {
   "id": "s2",
   "title": "The three Cs and the primary survey",
   "html": "<p>Once the scene is safe: <strong>Check</strong> the victim, <strong>Call</strong> the EMS, <strong>Care</strong> for the victim. The check is the <strong>primary survey (ABCDE)</strong>: Airway, Breathing, Circulation, Disability (neurological status including neck injury), Exposure/Environment. Call early and give an exact location (map, phone, GPS, landmarks); the Moroccan emergency number taught is <strong>15</strong>.</p><p><strong>A</strong>: is the airway open? After a fall or major trauma, suspect the cervical spine and apply spinal motion restriction; do not move the person unless unsafe. <strong>B</strong>: look, listen, feel for normal breathing for at most 10 seconds; listen for wheeze or stridor; look for swelling, choking and cyanosis; use pulse oximetry if available.</p>"
  },
  {
   "id": "s3",
   "title": "The unresponsive victim",
   "html": "<p>In a supine unresponsive victim the tongue can fall back and block the airway. Open it with a <strong>head tilt and chin lift</strong> (hand on forehead, fingertips under the chin) or a <strong>jaw thrust</strong> (modified jaw thrust in trauma); an improvised nasopharyngeal airway can help. Clear blood, vomit, loose dentures and debris with a two-finger sweep without pushing them deeper. If breathing adequately, turn the victim into the <strong>recovery position</strong> (arm bent or straight; prone variant; <strong>left side in pregnancy</strong>) and keep checking breathing until EMS arrives.</p>"
  },
  {
   "id": "s4",
   "title": "Choking",
   "html": "<p>Obstruction of the upper airway above the vocal cords by the tongue, broken teeth, dentures or food. <strong>Partial</strong>: the victim can speak or cough forcefully; encourage coughing and monitor. <strong>Complete</strong>: no speech, no air exchange, no cough; the universal choking sign (hands at the neck); untreated it leads to hypoxic cardiac arrest.</p><p><strong>Care</strong>: sweep visible material, remove loose dentures; give <strong>2 to 4 sharp back blows</strong> between the shoulder blades (victim bent forward); then the <strong>Heimlich manoeuvre</strong>: from behind, fist in the upper abdomen just below the ribs, 2 to 3 sudden firm squeezes. Small child: face down or upside down. <strong>Infant</strong>: face down on the forearm, head lower, <strong>5 back blows then 5 chest thrusts</strong>. <strong>Obese or pregnant</strong>: chest thrusts on the breastbone instead of the abdomen. A lying victim can also receive thrusts.</p>"
  }
 ],
