 "deeper": [
  {
   "title": "Why width matters for a tourniquet",
   "html": "<p>A narrow cord concentrates force on a thin strip of skin: it cuts and crushes nerves and muscle before it squeezes the artery shut. A band 7.5 to 10 cm wide spreads the same pressure over a larger area, closing the artery at lower pressure with less tissue damage.</p><p class='src'>Source: the lecture's tourniquet application slide.</p>"
  },
  {
   "title": "Why a sling helps a broken pelvis",
   "html": "<p>An open-book pelvic fracture enlarges the pelvic volume, and torn pelvic veins can lose litres of blood into that space. Binding the pelvis at the level of the greater trochanters closes the ring, reduces the volume the blood can fill and brings the bone ends together, which helps the bleeding stop.</p><p class='src'>Source: the lecture's pelvic sling slides.</p>"
  }
 ],
