 "deeper": [
  {
   "title": "Why cooling helps only early",
   "html": "<p>Heat keeps damaging tissue for several minutes after the source is removed, as stored heat spreads deeper. Early cooling pulls that heat out and limits the depth of the burn. After about 30 minutes the damage is already set, so cooling can only ease pain, which is exactly the time limit the lecture gives.</p><p class='src'>Source: the lecture's burn cooling slide.</p>"
  },
  {
   "title": "Why a full-face helmet has to come off",
   "html": "<p>A full-face helmet hides the airway and the face and makes ventilation impossible. Because of its bulk it also pushes a lying victim's head into flexion. Removing it carefully with two rescuers keeps the neck in line while giving access to the airway.</p><p class='src'>Source: the lecture's helmet removal slides.</p>"
  }
 ],
