 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Explain the Monro-Kellie doctrine.",
   "back": "The skull is a fixed-volume box of brain, blood and CSF. Increasing any component raises ICP; lowering ICP requires reducing one of them, which is how every ICP treatment works."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Give normal ICP and perfusion.",
   "back": "ICP 5 to 15 mmHg, raised at 20 or more. CPP = MAP − ICP. The brain is 2 to 3 percent of body mass but takes 20 percent of blood volume. Autoregulation keeps flow constant for CPP 60 to 160 mmHg; below 60 ischaemia, above 160 hypertensive encephalopathy. PaO2 and PaCO2 also affect flow."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe the ICP waveform and vicious circle.",
   "back": "Baseline with small rapid cardiac pulsations and larger slower respiratory waves. Raised ICP lowers CPP, causing ischaemia, which causes more swelling and further raises ICP."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Name the types of cerebral oedema.",
   "back": "Vasogenic, cytotoxic, interstitial and osmotic; blood-brain barrier dysfunction is central. Hydrocephalus shows enlarged ventricles with effaced sulci."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Summarise ICP management.",
   "back": "Steroids for vasogenic (tumour) oedema; glucose control; hypothermia (lowers flow, ICP, metabolism); skull trephination for deteriorating epidural haematoma; craniotomy or ventriculostomy for space-occupying lesions; shunts for hydrocephalus."
  },
  {
   "id": "x0",
   "type": "text",
   "front": "State the Monro-Kellie doctrine.",
   "back": "The cranium is a fixed-volume space containing brain, blood and CSF; an increase in one raises ICP; lowering ICP means reducing one of them."
  },
  {
   "id": "x1",
   "type": "text",
   "front": "Normal and raised ICP values?",
   "back": "Normal 5 to 15 mmHg in adults; raised ICP is 20 mmHg or more."
  },
  {
   "id": "x2",
   "type": "text",
   "front": "What is CPP and its autoregulation range?",
   "back": "CPP = MAP - ICP; CBF is kept constant for CPP 60 to 160 mmHg; below 60 ischaemia, above 160 hypertensive encephalopathy."
  },
  {
   "id": "x3",
   "type": "text",
   "front": "Four types of cerebral oedema?",
   "back": "Vasogenic (BBB breakdown, tumours), cytotoxic (cell swelling), interstitial (hydrocephalus), osmotic."
  },
  {
   "id": "x4",
   "type": "text",
   "front": "List the management options for raised ICP.",
   "back": "Steroids (vasogenic oedema), glucose control, hypothermia, skull trephination (epidural haematoma), craniotomy or ventriculostomy, shunts for hydrocephalus."
  },
  {
   "id": "x5",
   "type": "text",
   "front": "Why is raised ICP a vicious circle?",
   "back": "Raised ICP lowers CPP, causing ischaemia, which causes more swelling and raises ICP further."
  },
  {
   "id": "img-brain",
   "type": "image",
   "target": "brain",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Brain tissue. One of the three intracranial volumes; cerebral oedema enlarges it."
  },
  {
   "id": "img-csf",
   "type": "image",
   "target": "csf",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Cerebrospinal fluid. Accumulates in hydrocephalus; can be drained by ventriculostomy or shunt."
  },
  {
   "id": "img-blood",
   "type": "image",
   "target": "blood",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Cerebral blood. Its volume rises with vasodilation, for example from high PaCO2."
  },
  {
   "id": "img-icp",
   "type": "image",
   "target": "icp",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Monro-Kellie doctrine. Fixed-volume skull: more of one component means higher ICP unless another decreases."
  },
  {
   "id": "img-cpp",
   "type": "image",
   "target": "cpp",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Cerebral perfusion pressure. CPP = MAP - ICP; autoregulated between 60 and 160 mmHg."
  },
  {
   "id": "img-ischemia",
   "type": "image",
   "target": "ischemia",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Vicious circle. Low CPP causes ischaemia, which causes more swelling and higher ICP."
  }
 ],
 "deeper": [
  {
   "title": "Why a small extra volume can suddenly be fatal",
   "html": "<p>At first the skull compensates: CSF is pushed into the spinal canal and venous blood leaves the head, so ICP barely changes. Once these reserves are used up, the pressure-volume curve turns steep and a few extra millilitres cause a large jump in ICP. This is why a patient with a haematoma can talk, then deteriorate quickly.</p><p class='src'>Source: the lecture's pressure-volume relationship slide.</p>"
  },
  {
   "title": "Why CO2 matters to the brain",
   "html": "<p>Carbon dioxide dilates cerebral vessels. A rise in PaCO2 increases cerebral blood volume and therefore ICP, while a fall constricts vessels and lowers it. That is why ventilation of a head-injured patient is carefully controlled, as the lecture's PaO2/PaCO2 blood-flow figure shows.</p><p class='src'>Source: the lecture's cerebral blood flow slide.</p>"
  }
 ],
