   "front": "Describe renal blood flow and GFR.",
   "back": "RBF 20 percent of cardiac output. The glomerulus lies between afferent and efferent arterioles. GFR = Pnet x area; glomerular hydraulic pressure about 60 mmHg. Normal 120 (women) to 130 (men) mL/min/1.73 m², about 180 L/day, falling 1 mL/min/year after 40; estimated by creatinine clearance."
