   "back": "The commonest (40 to 55 percent): hypoperfusion from true hypovolaemia (haemorrhage, GI or renal losses, third spacing) or low effective arterial volume (cardiogenic or septic shock, cirrhosis, hypoalbuminaemia, anaphylaxis). Parenchyma intact; reverses with perfusion; prolonged, it causes ATN."
