 "deeper": [
  {
   "title": "Why adrenal crisis resists vasopressors",
   "html": "<p>Cortisol is permissive for catecholamines: it keeps vascular receptors responsive and supports their synthesis. Without cortisol, vessels respond poorly to noradrenaline and the heart may not even speed up. That is why the lecture says to think of adrenal crisis when hypotension persists despite fluids and several vasopressors.</p><p class='src'>Source: the lecture's adrenal crisis critical presentation slide.</p>"
  },
  {
   "title": "Why insulin can make DKA potassium fall dangerously",
   "html": "<p>In DKA potassium is pushed out of cells by acidosis and lost in the urine, so the blood level looks high while the body is depleted. Insulin drives potassium back into cells within hours, unmasking the deficit and risking arrhythmias. Hence 'avoid hypokalaemia' in the treatment list.</p><p class='src'>Source: the lecture's DKA pathophysiology and treatment slides.</p>"
  }
 ],
