 "deeper": [
  {
   "title": "Why PT and albumin, not enzymes, measure liver function",
   "html": "<p>Transaminases leak from damaged hepatocytes, so they measure injury, not how much liver still works; they can even fall as the liver dies. The liver alone makes albumin and most clotting factors, so a prolonged prothrombin time or low albumin shows that synthetic capacity is failing. The short half-life of clotting factors makes PT the faster warning.</p><p class='src'>Source: the lecture's liver function slides.</p>"
  },
  {
   "title": "Why mesenteric ischaemia hurts before the belly is tender",
   "html": "<p>Early on, the ischaemia is in the bowel mucosa and wall, which sends deep visceral pain but does not irritate the parietal peritoneum. Tenderness and rigidity only appear once the whole wall is necrotic and inflames the peritoneum. By then the bowel may be dead, which is why pain out of proportion to the examination must trigger CT angiography early.</p><p class='src'>Source: the lecture's mesenteric ischaemia pathophysiology slide.</p>"
  }
 ],
